import { ParameterValue, Tool, Command } from "@/components/commandly/types/flat";
import { generateCommand } from "@/components/commandly/utils/flat";
import { Button } from "@/components/ui/button";
import { CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { cn } from "@/lib/utils";
import { TerminalIcon, CopyIcon, SaveIcon } from "lucide-react";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { toast } from "sonner";

interface GeneratedCommandProps {
  tool: Tool;
  selectedCommand?: Command | null;
  parameterValues: Record<string, ParameterValue>;
  onSaveCommand?: (command: string) => void;
  useLongFlag?: boolean;
  children?: ReactNode;
}

interface GeneratedCommandContextValue {
  generatedCommand: string;
  useLongFlag: boolean;
  setUseLongFlag: (value: boolean) => void;
  supportsFlagPreference: boolean;
  onCopyCommand: () => void;
  onSaveCommand?: (command: string) => void;
}

const GeneratedCommandContext = createContext<GeneratedCommandContextValue | null>(null);

function useGeneratedCommandContext() {
  const context = useContext(GeneratedCommandContext);

  if (!context) {
    throw new Error("GeneratedCommand compound components must be used within GeneratedCommand.");
  }

  return context;
}

function GeneratedCommandRoot({
  tool,
  selectedCommand: providedCommand,
  parameterValues,
  onSaveCommand,
  useLongFlag = false,
  children,
}: GeneratedCommandProps) {
  const [prefersLongFlag, setPrefersLongFlag] = useState(useLongFlag);
  const supportsFlagPreference = useMemo(
    () =>
      tool.parameters.some(
        (parameter) =>
          parameter.parameterType !== "Argument" &&
          Boolean(parameter.shortFlag) &&
          Boolean(parameter.longFlag),
      ),
    [tool.parameters],
  );

  useEffect(() => {
    setPrefersLongFlag(useLongFlag);
  }, [useLongFlag]);

  const generatedCommand = useMemo(
    () =>
      generateCommand(tool, parameterValues, {
        selectedCommand: providedCommand,
        useLongFlag: prefersLongFlag,
      }),
    [tool, parameterValues, providedCommand, prefersLongFlag],
  );

  const copyCommand = useCallback(() => {
    navigator.clipboard.writeText(generatedCommand);
    toast("Command copied!");
  }, [generatedCommand]);

  const contextValue = useMemo(
    () => ({
      generatedCommand,
      useLongFlag: prefersLongFlag,
      setUseLongFlag: setPrefersLongFlag,
      supportsFlagPreference,
      onCopyCommand: copyCommand,
      onSaveCommand,
    }),
    [generatedCommand, prefersLongFlag, supportsFlagPreference, copyCommand, onSaveCommand],
  );

  return (
    <GeneratedCommandContext.Provider value={contextValue}>
      {generatedCommand ? (
        (children ?? (
          <div className="min-w-0 space-y-4">
            <GeneratedCommandOutput />
            <GeneratedCommandActions />
          </div>
        ))
      ) : (
        <GeneratedCommandEmptyState />
      )}
    </GeneratedCommandContext.Provider>
  );
}

function GeneratedCommandToolbar({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      className={cn("flex flex-wrap items-center justify-end gap-2", className)}
      {...props}
    />
  );
}

function GeneratedCommandHeader({
  children,
  className,
  ...props
}: ComponentProps<typeof CardHeader>) {
  return (
    <CardHeader
      className={cn("flex flex-row items-center justify-between gap-3 space-y-0", className)}
      {...props}
    >
      <CardTitle className="flex items-center gap-2">
        <TerminalIcon className="h-5 w-5" />
        Generated Command
      </CardTitle>
      {children}
    </CardHeader>
  );
}

function GeneratedCommandFlagPreference({
  className,
  ...props
}: Omit<ComponentProps<typeof Switch>, "checked" | "onCheckedChange">) {
  const { supportsFlagPreference, useLongFlag, setUseLongFlag } = useGeneratedCommandContext();

  if (!supportsFlagPreference) return null;

  return (
    <Label className="shrink-0 gap-2 text-xs text-muted-foreground">
      <span className="font-mono tracking-[0.12em] uppercase">Long flags</span>
      <Switch
        checked={useLongFlag}
        onCheckedChange={setUseLongFlag}
        aria-label="Long flags"
        className={className}
        {...props}
      />
    </Label>
  );
}

function GeneratedCommandOutput({ className, ...props }: ComponentProps<"div">) {
  const { generatedCommand } = useGeneratedCommandContext();

  return (
    <div
      className={cn("overflow-x-auto rounded bg-muted p-4 font-mono text-sm", className)}
      {...props}
    >
      <div className="min-w-max whitespace-nowrap">{generatedCommand}</div>
    </div>
  );
}

function GeneratedCommandActions({ className, ...props }: ComponentProps<"div">) {
  const { generatedCommand, onCopyCommand, onSaveCommand } = useGeneratedCommandContext();

  return (
    <div
      className={cn("flex flex-col gap-2 sm:flex-row", className)}
      {...props}
    >
      <Button
        onClick={onCopyCommand}
        variant="outline"
        className="w-full sm:flex-1"
      >
        <CopyIcon className="mr-2 h-4 w-4" />
        Copy Command
      </Button>
      {onSaveCommand && (
        <Button
          onClick={() => onSaveCommand(generatedCommand)}
          variant="outline"
          className="w-full sm:flex-1"
        >
          <SaveIcon className="mr-2 h-4 w-4" />
          Save Command
        </Button>
      )}
    </div>
  );
}

function GeneratedCommandEmptyState() {
  return (
    <div className="py-8 text-center">
      <TerminalIcon className="mx-auto mb-4 h-12 w-12 text-muted-foreground" />
      <p className="text-muted-foreground">Configure parameters to generate the command.</p>
    </div>
  );
}

export const GeneratedCommand = Object.assign(GeneratedCommandRoot, {
  Header: GeneratedCommandHeader,
  Toolbar: GeneratedCommandToolbar,
  FlagPreference: GeneratedCommandFlagPreference,
  Output: GeneratedCommandOutput,
  Actions: GeneratedCommandActions,
  EmptyState: GeneratedCommandEmptyState,
});

import { Tool } from "@/components/commandly/types/flat";
import { exportToStructuredJSON } from "@/components/commandly/utils/flat";
import { convertToNestedStructure } from "@/components/commandly/utils/nested";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardAction, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Command as UICommand,
  CommandGroup,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { ScrollArea, ScrollBar } from "@/components/ui/scroll-area";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import { CheckIcon, ChevronsUpDownIcon, CopyIcon, Edit2Icon, XIcon } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";

const jsonOptions = [
  { value: "nested", label: "Nested" },
  { value: "flat", label: "Flat" },
];

type DiffLine = { type: "same" | "added" | "removed"; text: string };

function diffLines(before: string, after: string): DiffLine[] {
  const a = before.split("\n");
  const b = after.split("\n");
  const m = a.length;
  const n = b.length;
  const dp = Array.from({ length: m + 1 }, () => new Array<number>(n + 1).fill(0));
  for (let i = 1; i <= m; i++)
    for (let j = 1; j <= n; j++)
      dp[i][j] =
        a[i - 1] === b[j - 1] ? dp[i - 1][j - 1] + 1 : Math.max(dp[i - 1][j], dp[i][j - 1]);
  const result: DiffLine[] = [];
  let i = m,
    j = n;
  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && a[i - 1] === b[j - 1]) {
      result.unshift({ type: "same", text: a[i - 1] });
      i--;
      j--;
    } else if (j > 0 && (i === 0 || dp[i][j - 1] >= dp[i - 1][j])) {
      result.unshift({ type: "added", text: b[j - 1] });
      j--;
    } else {
      result.unshift({ type: "removed", text: a[i - 1] });
      i--;
    }
  }
  return result;
}

interface JsonTypeComponentProps {
  tool: Tool;
  originalTool?: Tool;
  onApply?: (tool: Tool) => void;
}

export function JsonOutput({ tool, originalTool, onApply }: JsonTypeComponentProps) {
  const [open, setOpen] = useState(false);
  const [jsonString, setJsonString] = useState<string>();
  const [originalJsonString, setOriginalJsonString] = useState<string>();
  const [jsonType, setJsonType] = useState<"nested" | "flat">("flat");
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState("");
  const [showDiff, setShowDiff] = useState(true);

  useEffect(() => {
    const config =
      jsonType === "flat" ? exportToStructuredJSON(tool) : convertToNestedStructure(tool);
    setJsonString(JSON.stringify(config, null, 2));
  }, [jsonType, tool]);

  useEffect(() => {
    if (!originalTool) {
      setOriginalJsonString(undefined);
      return;
    }
    const config =
      jsonType === "flat"
        ? exportToStructuredJSON(originalTool)
        : convertToNestedStructure(originalTool);
    setOriginalJsonString(JSON.stringify(config, null, 2));
  }, [jsonType, originalTool]);

  const diff = useMemo(() => {
    if (!originalJsonString || !jsonString || originalJsonString === jsonString) return null;
    return diffLines(originalJsonString, jsonString);
  }, [originalJsonString, jsonString]);

  const diffStats = useMemo(() => {
    if (!diff) return null;
    const added = diff.filter((l) => l.type === "added").length;
    const removed = diff.filter((l) => l.type === "removed").length;
    return { added, removed };
  }, [diff]);

  const handleEditToggle = () => {
    setEditValue(jsonString ?? "");
    setIsEditing(true);
  };

  const handleApply = () => {
    try {
      const parsed = JSON.parse(editValue) as Tool;
      onApply!(parsed);
      setIsEditing(false);
    } catch {
      toast.error("Invalid JSON", { description: "Please fix the JSON before applying." });
    }
  };

  const handleCancel = () => {
    setIsEditing(false);
    setEditValue("");
  };

  return (
    <Card className="max-w-full">
      <CardHeader className="gap-4">
        <CardTitle className="flex min-w-0 flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex min-w-0 flex-col gap-2 sm:flex-row sm:items-center">
            <span className="text-sm">Output type:</span>
            <Popover
              open={open}
              onOpenChange={setOpen}
            >
              <PopoverTrigger asChild>
                <Button
                  variant="outline"
                  role="combobox"
                  aria-expanded={open}
                  className="w-full min-w-0 justify-between sm:w-48"
                >
                  {jsonOptions.find((option) => option.value === jsonType)?.label}
                  <ChevronsUpDownIcon className="opacity-50" />
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-(--radix-popover-trigger-width) min-w-40 p-0 sm:w-48">
                <UICommand>
                  <CommandList>
                    <CommandGroup>
                      {jsonOptions.map((option) => (
                        <CommandItem
                          key={option.value}
                          value={option.value}
                          onSelect={(currentValue) => {
                            setJsonType(currentValue as "nested" | "flat");
                            setOpen(false);
                          }}
                        >
                          {option.label}
                          <CheckIcon
                            className={cn(
                              "ml-auto h-4 w-4",
                              jsonType === option.value ? "opacity-100" : "opacity-0",
                            )}
                          />
                        </CommandItem>
                      ))}
                    </CommandGroup>
                  </CommandList>
                </UICommand>
              </PopoverContent>
            </Popover>
          </div>
        </CardTitle>
        <div className="flex shrink-0 items-center gap-3 self-start sm:self-auto">
          {onApply && !isEditing && (
            <CardAction
              className="rounded-md"
              onClick={handleEditToggle}
            >
              <Edit2Icon className="h-4 w-4 dark:stroke-primary" />
            </CardAction>
          )}
          {onApply && isEditing && (
            <CardAction
              className="rounded-md"
              onClick={handleCancel}
            >
              <XIcon className="h-4 w-4 dark:stroke-primary" />
            </CardAction>
          )}
          <CardAction
            className="rounded-md"
            onClick={() => {
              navigator.clipboard.writeText(jsonString!);
              toast("Copied!");
            }}
          >
            <CopyIcon className="h-4 w-4 dark:stroke-primary" />
          </CardAction>
        </div>
      </CardHeader>
      <CardContent>
        {diffStats && !isEditing && (
          <div className="mb-2 flex flex-wrap items-center gap-2">
            {diffStats.added > 0 && (
              <Badge
                variant="outline"
                className="border-green-500/40 bg-green-500/10 text-green-600 dark:text-green-400"
              >
                +{diffStats.added} added
              </Badge>
            )}
            {diffStats.removed > 0 && (
              <Badge
                variant="outline"
                className="border-red-500/40 bg-red-500/10 text-red-600 dark:text-red-400"
              >
                -{diffStats.removed} removed
              </Badge>
            )}
            <Button
              variant="ghost"
              size="sm"
              className="h-6 px-2 text-xs sm:ml-auto"
              onClick={() => setShowDiff((v) => !v)}
            >
              {showDiff ? "Full view" : "Diff view"}
            </Button>
          </div>
        )}
        {isEditing ? (
          <div className="flex flex-col gap-2">
            <ScrollArea
              className="max-w-full *:data-radix-scroll-area-viewport:max-h-[calc(100vh-360px)]"
              type="hover"
            >
              <Textarea
                className="min-h-80 font-mono text-sm sm:min-h-[calc(100vh-400px)]"
                value={editValue}
                onChange={(e) => setEditValue(e.target.value)}
                spellCheck={false}
              />
              <ScrollBar orientation="vertical" />
              <ScrollBar orientation="horizontal" />
            </ScrollArea>
            <div className="flex justify-end gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={handleCancel}
              >
                Cancel
              </Button>
              <Button
                size="sm"
                onClick={handleApply}
              >
                Apply
              </Button>
            </div>
          </div>
        ) : diff && showDiff ? (
          <ScrollArea
            className="max-w-full *:data-radix-scroll-area-viewport:max-h-[calc(100vh-320px)]"
            type="hover"
          >
            <pre className="w-fit min-w-full rounded-md font-mono text-sm whitespace-pre">
              {diff.map((line, idx) => (
                <div
                  key={idx}
                  className={cn(
                    "px-1",
                    line.type === "added" && "bg-green-500/10 text-green-700 dark:text-green-400",
                    line.type === "removed" && "bg-red-500/10 text-red-700 dark:text-red-400",
                    line.type === "same" && "text-foreground/80",
                  )}
                >
                  <span className="opacity-50 select-none">
                    {line.type === "added" ? "+ " : line.type === "removed" ? "- " : "  "}
                  </span>
                  {line.text}
                </div>
              ))}
            </pre>
            <ScrollBar orientation="vertical" />
            <ScrollBar orientation="horizontal" />
          </ScrollArea>
        ) : (
          <ScrollArea
            className="max-w-full *:data-radix-scroll-area-viewport:max-h-[calc(100vh-320px)]"
            type="hover"
          >
            <pre className="w-fit min-w-full rounded-md bg-card font-mono text-sm whitespace-pre dark:text-gray-200">
              {jsonString}
            </pre>
            <ScrollBar orientation="vertical" />
            <ScrollBar orientation="horizontal" />
          </ScrollArea>
        )}
      </CardContent>
    </Card>
  );
}

import { ParameterValue } from "@/components/commandly/types/flat";
import { Command, Tool } from "@/components/commandly/types/flat";
import {
  ParameterRenderContext,
  ParameterRendererEntry,
} from "@/components/commandly/types/renderer";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Command as UICommand,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { MultiSelect } from "@/components/ui/multi-select";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Switch } from "@/components/ui/switch";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import { CheckIcon, ChevronsUpDownIcon, InfoIcon, PlusIcon, XIcon } from "lucide-react";
import React, { useMemo } from "react";

const findDefaultCommand = (tool: Tool): Command | null => {
  const nameMatchCommand = tool.commands.find(
    (command) => command.name.toLowerCase() === tool.binaryName.toLowerCase(),
  );
  if (nameMatchCommand) return nameMatchCommand;

  return tool.commands.length > 0 ? tool.commands[0] : null;
};

interface ParameterLabelProps {
  name: string;
  longFlag?: string;
  shortFlag?: string;
  isRequired?: boolean;
  isGlobal?: boolean;
  description?: string;
  className?: string;
  children?: React.ReactNode;
}

function ParameterLabel({
  name,
  longFlag,
  shortFlag,
  isRequired,
  isGlobal,
  description,
  className,
  children,
}: ParameterLabelProps) {
  return (
    <Label className={className}>
      {name}
      {(longFlag || shortFlag) && (
        <span className="ml-1 text-muted-foreground">
          ({[longFlag, shortFlag].filter(Boolean).join(", ")})
        </span>
      )}
      {isRequired && <span className="ml-1 text-destructive">*</span>}
      {description?.trim() && (
        <Tooltip>
          <TooltipTrigger>
            <InfoIcon className="h-3.5 w-3.5" />
          </TooltipTrigger>
          <TooltipContent>
            <span>{description}</span>
          </TooltipContent>
        </Tooltip>
      )}
      {children}
      {isGlobal && (
        <Badge
          variant="outline"
          className="ml-2 text-xs"
        >
          global
        </Badge>
      )}
    </Label>
  );
}

function FlagInput({ parameter, value, onUpdate }: ParameterRenderContext) {
  return (
    <div className="flex items-center space-x-2">
      <Switch
        checked={value === "true" || value === true}
        onCheckedChange={onUpdate}
      />
      <ParameterLabel
        className="flex-1 select-auto"
        name={parameter.name}
        longFlag={parameter.longFlag}
        shortFlag={parameter.shortFlag}
        isRequired={parameter.isRequired}
        isGlobal={parameter.isGlobal}
        description={parameter.description}
      />
    </div>
  );
}

function OptionEnumInput({ parameter, value, onUpdate }: ParameterRenderContext) {
  const [open, setOpen] = React.useState(false);
  const separator = parameter.enum?.separator || ",";
  const options =
    parameter.enum?.values?.map((e) => ({
      value: e.value,
      label: e.displayName || e.value,
    })) ?? [];

  const label = (
    <ParameterLabel
      className="select-auto"
      name={parameter.name}
      longFlag={parameter.longFlag}
      shortFlag={parameter.shortFlag}
      isRequired={parameter.isRequired}
      isGlobal={parameter.isGlobal}
      description={parameter.description}
    />
  );

  if (parameter.enum?.allowMultiple) {
    const selected = Array.isArray(value)
      ? (value as string[]).filter(Boolean)
      : value
        ? (value as string).split(separator).filter(Boolean)
        : [];
    return (
      <div className="space-y-2">
        {label}
        <MultiSelect
          options={options}
          defaultValue={selected}
          onValueChange={(vals) => onUpdate(vals.join(separator))}
          placeholder="Select options"
        />
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {label}
      <Popover
        open={open}
        onOpenChange={setOpen}
      >
        <PopoverTrigger asChild>
          <Button
            variant="outline"
            role="combobox"
            aria-expanded={open}
            className="w-full justify-between font-normal"
          >
            {options.find((o) => o.value === value)?.label ?? "Select an option"}
            <ChevronsUpDownIcon className="opacity-50" />
          </Button>
        </PopoverTrigger>
        <PopoverContent
          className="w-[--radix-popover-trigger-width] p-0"
          align="start"
        >
          <UICommand>
            <CommandInput placeholder="Search..." />
            <CommandList>
              <CommandEmpty>No option found.</CommandEmpty>
              <CommandGroup>
                {options.map((option) => (
                  <CommandItem
                    key={option.value}
                    value={option.value}
                    onSelect={(currentValue) => {
                      onUpdate(currentValue === value ? "" : currentValue);
                      setOpen(false);
                    }}
                  >
                    {option.label}
                    <CheckIcon
                      className={cn(
                        "ml-auto",
                        value === option.value ? "opacity-100" : "opacity-0",
                      )}
                    />
                  </CommandItem>
                ))}
              </CommandGroup>
            </CommandList>
          </UICommand>
        </PopoverContent>
      </Popover>
    </div>
  );
}

function OptionBooleanInput({ parameter, value, onUpdate }: ParameterRenderContext) {
  return (
    <div className="flex items-center space-x-2">
      <Switch
        checked={value === "true" || value === true}
        onCheckedChange={(checked) => onUpdate(checked.toString())}
      />
      <ParameterLabel
        className="flex-1 select-auto"
        name={parameter.name}
        longFlag={parameter.longFlag}
        shortFlag={parameter.shortFlag}
        isRequired={parameter.isRequired}
        isGlobal={parameter.isGlobal}
        description={parameter.description}
      />
    </div>
  );
}

function OptionTextInput({ parameter, value, onUpdate }: ParameterRenderContext) {
  return (
    <div className="space-y-2">
      <ParameterLabel
        className="flex-1 select-auto"
        name={parameter.name}
        longFlag={parameter.longFlag}
        shortFlag={parameter.shortFlag}
        isRequired={parameter.isRequired}
        isGlobal={parameter.isGlobal}
        description={parameter.description}
      />
      <Input
        type={parameter.dataType === "Number" ? "number" : "text"}
        value={parameter.dataType === "Number" ? (value as number) : (value as string)}
        onChange={(e) => onUpdate(e.target.value)}
        placeholder="Enter value"
      />
    </div>
  );
}

function ArgumentInput({ parameter, value, onUpdate }: ParameterRenderContext) {
  return (
    <div className="space-y-2">
      <ParameterLabel
        name={parameter.name}
        isRequired={parameter.isRequired}
        description={parameter.description}
      >
        <Badge
          variant="secondary"
          className="ml-2 text-xs"
        >
          {parameter.parameterType}
          {parameter.position !== undefined && ` (${parameter.position})`}
        </Badge>
      </ParameterLabel>
      <Input
        type={parameter.dataType === "Number" ? "number" : "text"}
        value={parameter.dataType === "Number" ? (value as number) : (value as string)}
        onChange={(e) => onUpdate(e.target.value)}
        placeholder="Enter value"
      />
    </div>
  );
}

interface RepeatableWrapperProps {
  parameter: ParameterRenderContext["parameter"];
  value: ParameterRenderContext["value"];
  onUpdate: ParameterRenderContext["onUpdate"];
  renderEntry: ParameterRendererEntry["component"];
}

function RepeatableWrapper({ parameter, value, onUpdate, renderEntry }: RepeatableWrapperProps) {
  const toArray = (v: ParameterRenderContext["value"]): string[] => {
    if (Array.isArray(v)) return v;
    if (v !== undefined && v !== "" && v !== false) return [String(v)];
    return [""];
  };

  const values = toArray(value);

  const updateAt = (index: number, val: ParameterRenderContext["value"]) => {
    const next = [...values];
    next[index] = String(val);
    onUpdate(next);
  };

  const addRow = () => onUpdate([...values, ""]);

  const removeAt = (index: number) => {
    const next = values.filter((_, i) => i !== index);
    onUpdate(next);
  };

  return (
    <div className="space-y-2">
      {values.map((val, index) => (
        <div
          key={index}
          className="flex items-start gap-2"
        >
          <div className="flex-1">
            {renderEntry({ parameter, value: val, onUpdate: (v) => updateAt(index, v) })}
          </div>
          {index > 0 && (
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="mt-6 shrink-0"
              onClick={() => removeAt(index)}
            >
              <XIcon className="h-4 w-4" />
            </Button>
          )}
        </div>
      ))}
      <Button
        type="button"
        variant="ghost"
        size="sm"
        className="h-7 px-2 text-muted-foreground"
        onClick={addRow}
      >
        <PlusIcon className="mr-1 h-3.5 w-3.5" />
        Add another
      </Button>
    </div>
  );
}

export function defaultComponents(): ParameterRendererEntry[] {
  return [
    { condition: (p) => p.parameterType === "Flag", component: (ctx) => <FlagInput {...ctx} /> },
    {
      condition: (p) => p.parameterType === "Argument",
      component: (ctx) => <ArgumentInput {...ctx} />,
    },
    {
      condition: (p) => p.parameterType === "Option" && p.dataType === "Enum",
      component: (ctx) => <OptionEnumInput {...ctx} />,
    },
    {
      condition: (p) => p.parameterType === "Option" && p.dataType === "Boolean",
      component: (ctx) => <OptionBooleanInput {...ctx} />,
    },
    {
      condition: (p) => p.parameterType === "Option",
      component: (ctx) => <OptionTextInput {...ctx} />,
    },
  ];
}

interface ToolRendererProps {
  selectedCommand?: Command | null;
  tool: Tool;
  catalog?: ParameterRendererEntry[];
  parameterValues: Record<string, ParameterValue>;
  updateParameterValue: (parameterKey: string, value: ParameterValue) => void;
}

export function ToolRenderer({
  selectedCommand: providedCommand,
  tool,
  catalog = defaultComponents(),
  parameterValues,
  updateParameterValue,
}: ToolRendererProps) {
  const selectedCommand =
    providedCommand === undefined ? findDefaultCommand(tool) : providedCommand;
  const hasCommands = tool.commands.length > 0;

  const visibleParameters = useMemo(() => {
    if (!hasCommands || !selectedCommand) {
      return tool.parameters.filter((p) => !p.commandKey || p.isGlobal);
    }
    return tool.parameters.filter(
      (param) => param.commandKey === selectedCommand?.key || param.isGlobal,
    );
  }, [tool, hasCommands, selectedCommand]);

  return (
    <React.Fragment>
      <div className="space-y-4">
        {visibleParameters.length > 0 ? (
          visibleParameters.map((parameter) => {
            const value = parameterValues[parameter.key] ?? "";
            const onUpdate = (val: ParameterValue) => updateParameterValue(parameter.key, val);
            const entry = catalog.find((e) => e.condition(parameter));
            if (!entry) return null;
            return (
              <React.Fragment key={parameter.key}>
                {parameter.isRepeatable ? (
                  <RepeatableWrapper
                    parameter={parameter}
                    value={value}
                    onUpdate={onUpdate}
                    renderEntry={entry.component}
                  />
                ) : (
                  entry.component({ parameter, value, onUpdate })
                )}
              </React.Fragment>
            );
          })
        ) : (
          <p className="text-sm text-muted-foreground">No parameters available for this command.</p>
        )}
      </div>
    </React.Fragment>
  );
}

